import{_ as i,o as a,c as s,ah as t}from"./chunks/framework.ojwJKwrc.js";const u=JSON.parse('{"title":"Heliodor Linux Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks/heliodor.md","filePath":"benchmarks/heliodor.md"}'),o={name:"benchmarks/heliodor.md"};function n(r,e,l,h,d,c){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="heliodor-linux-benchmark" tabindex="-1">Heliodor Linux Benchmark <a class="header-anchor" href="#heliodor-linux-benchmark" aria-label="Permalink to &quot;Heliodor Linux Benchmark&quot;">​</a></h1><p>Heliodor is Celox&#39;s large external Veryl workload. It boots a pinned Linux image and compares Celox&#39;s native and tiered JIT backends with synchronous <code>veryl-cc</code> execution using the same design revision and input workload. The tiered runner starts on the interpreter while native code is generated in the background, then promotes the live simulation at a scheduler safe point. Cranelift Linux boot measurements are not collected or published because their runtime is outside the useful scale of this comparison.</p><h2 id="what-the-benchmark-answers" tabindex="-1">What the benchmark answers <a class="header-anchor" href="#what-the-benchmark-answers" aria-label="Permalink to &quot;What the benchmark answers&quot;">​</a></h2><p>The benchmark separates two questions:</p><ol><li>How long does Celox take to compile the design?</li><li>How quickly does the generated simulator execute the complete workload?</li><li>How long does tiered execution take from startup through Linux completion while compilation overlaps simulation?</li></ol><p>Only the second measurement is used for generated-code throughput comparisons. A partial boot, projected completion time, or compile-only result is not a successful execution result.</p><h2 id="valid-result" tabindex="-1">Valid result <a class="header-anchor" href="#valid-result" aria-label="Permalink to &quot;Valid result&quot;">​</a></h2><p>A run is accepted only when it:</p><ul><li>uses the pinned Heliodor and workload revisions;</li><li>reaches the configured Linux completion marker;</li><li>records compilation and execution separately;</li><li>compares runners built from the intended Celox and Veryl revisions;</li><li>preserves the logs needed to diagnose a timeout or semantic mismatch.</li><li>proves that the tiered run promoted and executed at least one generated-code evaluation before Linux completed.</li></ul><p>This fixed completion marker prevents faster failures or incomplete boots from being reported as performance improvements.</p><h2 id="run-locally" tabindex="-1">Run locally <a class="header-anchor" href="#run-locally" aria-label="Permalink to &quot;Run locally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>To run only the tiered JIT benchmark:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_RUNNERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">celox-tiered</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>The first run needs network access to obtain the pinned Heliodor checkout. The script prints the selected revisions, build configuration, completion status, and timings. Use the same machine and configuration for before/after comparisons.</p><p>Published results appear in the <strong>Heliodor Linux</strong> section of the <a href="./">benchmark dashboard</a>.</p>',16)])])}const m=i(o,[["render",n]]);export{u as __pageData,m as default};
